#include "plugins/PluginManager.h"
#include "plugins/ContentQueries.h"
#include <algorithm>
#include <cmath>

namespace Plugins {
namespace {
void require(bool ok,const char* error){if(!ok)throw std::runtime_error(error);}
uint32_t integer(const Json& j,const char* key,uint32_t fallback){const double n=j.numeric(key,fallback);require(n>=0&&n<=UINT32_MAX&&std::floor(n)==n,"Invalid capability integer");return static_cast<uint32_t>(n);}
void vector(const Json& j,const char* key,float* out,size_t n){if(!j.has(key))return;const auto& a=j.at(key);require(a.type==Json::Type::Array&&a.array.size()==n,"Invalid capability vector");for(size_t i=0;i<n;++i){require(a.array[i].type==Json::Type::Number,"Vector requires numbers");out[i]=static_cast<float>(a.array[i].number);}}
int32_t coordinate(const Json& j,const char* key){const double n=j.numeric(key,0);require(std::floor(n)==n&&std::abs(n)<=30000000,"Invalid structure coordinate");return static_cast<int32_t>(n);}
uint64_t domain(const Json& j){if(!j.has("seed_domain"))return 0;const auto& v=j.at("seed_domain");if(v.type==Json::Type::String){size_t used=0;const auto result=std::stoull(v.string,&used,0);require(used==v.string.size()&&!v.string.empty()&&v.string[0]!='-',"Invalid seed domain");return result;}require(v.type==Json::Type::Number&&v.number>=0&&v.number<=9007199254740991.0&&std::floor(v.number)==v.number,"Large seed domains require string");return static_cast<uint64_t>(v.number);}
}
void PluginManager::loadCapabilities(MC_PluginContext& ctx,const Json& data){
    auto each=[&](const char* key,auto fn){if(!data.has(key))return;const auto& a=data.at(key);require(a.type==Json::Type::Array&&a.array.size()<=4096,"Invalid capability array");for(const auto& j:a.array){require(j.type==Json::Type::Object,"Capability requires object");fn(j);}};
    auto dimension=[](const Json& j){return resolveDimension(j.text("dimension","minecraftc:overworld"));};
    each("block_behaviors",[&](const Json& j){MC_BlockBehavior d{};d.size=sizeof(d);const auto block=j.at("block").text(),harvest=j.text("harvest_item"),replacement=j.text("harvest_replacement"),action=j.text("action");d.block=block.c_str();d.harvest_item=harvest.c_str();d.harvest_replacement=replacement.c_str();d.action=action.c_str();d.climbable=j.flag("climbable",false);d.replaceable=j.flag("replaceable",false);d.support=integer(j,"support",0);d.fire_encouragement=integer(j,"fire_encouragement",0);d.fire_flammability=integer(j,"fire_flammability",0);d.contact_damage=static_cast<float>(j.numeric("contact_damage",0));d.harvest_count=integer(j,"harvest_count",harvest.empty()?0:1);d.harvest_reset_ticks=integer(j,"harvest_reset_ticks",0);MC_BlockBehaviorV2 v{};v.size=sizeof(v);v.base=d;
        if(j.has("light_dampening")){v.fields|=MC_BLOCK_LIGHT;v.light_dampening=integer(j,"light_dampening",0);}
        if(j.has("tags")){v.fields|=MC_BLOCK_TAGS;v.tags=integer(j,"tags",0);}
        if(j.has("substrate_tags")){v.fields|=MC_BLOCK_SUBSTRATE;v.substrate_tags=integer(j,"substrate_tags",0);}
        std::vector<std::string> keys;std::vector<MC_BreakDrop> drops;
        if(j.has("break_drops")){v.fields|=MC_BLOCK_DROPS;const auto& a=j.at("break_drops");require(a.type==Json::Type::Array&&a.array.size()<=16,"Invalid break drops");for(const auto& r:a.array)keys.push_back(r.at("item").text());for(size_t i=0;i<keys.size();++i){const auto& r=a.array[i];drops.push_back({keys[i].c_str(),integer(r,"minimum",1),integer(r,"maximum",1),integer(r,"numerator",1),integer(r,"denominator",1)});}v.drops=drops.data();v.drop_count=static_cast<uint32_t>(drops.size());}
        blockBehaviorV2(ctx,v);});
    each("item_behaviors",[&](const Json& j){const auto item=j.at("item").text(),action=j.text("action"),dim=j.text("dimension");MC_ItemBehavior d{sizeof(d),item.c_str(),action.c_str(),dim.c_str()};MC_ItemBehaviorV2 v{};v.size=sizeof(v);v.base=d;if(j.has("fuel_ticks")){v.fields|=MC_ITEM_FUEL;v.fuel_ticks=integer(j,"fuel_ticks",0);}if(j.has("tags")){v.fields|=MC_ITEM_TAGS;v.tags=integer(j,"tags",0);}itemBehaviorV2(ctx,v);});
    each("loot_tables",[&](const Json& j){const auto key=j.at("key").text(),revision=j.at("revision").text();const auto& a=j.at("entries");require(a.type==Json::Type::Array,"Loot entries require array");std::vector<std::string> keys;std::vector<MC_LootEntry> entries;for(const auto& e:a.array)keys.push_back(e.at("item").text());for(size_t i=0;i<keys.size();++i){const auto& e=a.array[i];entries.push_back({keys[i].c_str(),integer(e,"minimum",1),integer(e,"maximum",1),integer(e,"chance",100)});}MC_LootTable d{sizeof(d),key.c_str(),revision.c_str(),entries.data(),static_cast<uint32_t>(entries.size())};lootTable(ctx,d);});
    each("structures",[&](const Json& j){MC_StructureDefinition d{};d.size=sizeof(d);d.dimension=dimension(j);const auto key=j.at("key").text(),name=j.text("name",key),revision=j.at("revision").text();d.key=key.c_str();d.name=name.c_str();d.revision=revision.c_str();d.cell_size=integer(j,"cell_size",64);d.chance=integer(j,"chance",10);d.radius=integer(j,"radius",8);d.height=integer(j,"height",16);d.terrain_tolerance=integer(j,"terrain_tolerance",2);d.seed_domain=domain(j);const auto& a=j.at("blocks");require(a.type==Json::Type::Array&&a.array.size()<=MC_MAX_STRUCTURE_BLOCKS,"Invalid template blocks");std::vector<std::string> loot;std::vector<MC_StructureBlock> blocks;for(const auto& b:a.array)loot.push_back(b.text("loot"));for(size_t i=0;i<loot.size();++i){const auto& b=a.array[i];const auto block=b.at("block").text();reference(ctx,block);blocks.push_back({coordinate(b,"x"),coordinate(b,"y"),coordinate(b,"z"),static_cast<uint16_t>(resolveBlock(block)),loot[i].c_str()});}d.blocks=blocks.data();d.count=static_cast<uint32_t>(blocks.size());structure(ctx,d);});
    each("player_actions",[&](const Json& j){const auto key=j.at("key").text(),dim=j.text("dimension");MC_PlayerAction d{};d.size=sizeof(d);d.key=key.c_str();d.dimension=dim.c_str();d.kind=integer(j,"kind",0);d.range=static_cast<float>(j.numeric("range",32));d.cooldown=static_cast<float>(j.numeric("cooldown",0));d.durability=integer(j,"durability",0);playerAction(ctx,d);});
    each("environments",[&](const Json& j){const auto key=j.at("key").text();MC_EnvironmentProfile d{};d.size=sizeof(d);d.key=key.c_str();d.dimension=dimension(j);auto& p=d.parameters;p.size=sizeof(p);p.dimension=d.dimension;p.sky_style=integer(j,"sky_style",0);p.clouds=j.flag("clouds",true);p.sun_size=static_cast<float>(j.numeric("sun_size",1));p.moon_size=static_cast<float>(j.numeric("moon_size",1));d.override_parameters=integer(j,"override_parameters",0);p.day_phase=static_cast<float>(j.numeric("day_phase",0));p.daylight=static_cast<float>(j.numeric("daylight",1));p.star_intensity=static_cast<float>(j.numeric("star_intensity",0));p.rain=static_cast<float>(j.numeric("rain",0));p.thunder=static_cast<float>(j.numeric("thunder",0));p.lightning=static_cast<float>(j.numeric("lightning",0));p.sun_direction[1]=p.light_direction[1]=1;p.moon_direction[1]=-1;vector(j,"sun_direction",p.sun_direction,3);vector(j,"moon_direction",p.moon_direction,3);vector(j,"light_direction",p.light_direction,3);vector(j,"zenith",p.colors.zenith,3);vector(j,"horizon",p.colors.horizon,3);vector(j,"fog",p.colors.fog,3);vector(j,"ambient_color",p.colors.ambient_color,3);vector(j,"direct_color",p.colors.direct_color,3);p.colors.ambient_intensity=static_cast<float>(j.numeric("ambient_intensity",1));p.colors.direct_intensity=static_cast<float>(j.numeric("direct_intensity",1));environmentProfile(ctx,d);});
    each("particles",[&](const Json& j){const auto key=j.at("key").text(),material=j.at("material").text();MC_ParticleDefinition d{};d.size=sizeof(d);d.key=key.c_str();d.material=material.c_str();std::fill(std::begin(d.color),std::end(d.color),1);vector(j,"color",d.color,4);vector(j,"velocity",d.velocity,3);d.lifetime=static_cast<float>(j.numeric("lifetime",1));d.scale=static_cast<float>(j.numeric("scale",.1));d.gravity=static_cast<float>(j.numeric("gravity",0));particleType(ctx,d);});
    each("held_models",[&](const Json& j){const auto item=j.at("item").text(),path=j.at("path").text();MC_HeldModel d{};d.size=sizeof(d);d.item=item.c_str();d.path=path.c_str();for(int i=0;i<16;++i)d.first_person[i]=d.third_person[i]=(i%5==0)?1:0;vector(j,"first_person",d.first_person,16);vector(j,"third_person",d.third_person,16);heldModel(ctx,d);});
    each("playlists",[&](const Json& j){const auto key=j.at("key").text();const auto& a=j.at("tracks");require(a.type==Json::Type::Array,"Playlist tracks require array");std::vector<std::string> paths;std::vector<const char*> tracks;for(const auto& t:a.array)paths.push_back(t.text());for(const auto& t:paths)tracks.push_back(t.c_str());MC_MusicPlaylist d{sizeof(d),dimension(j),uint32_t(j.flag("menu",false)),uint32_t(j.flag("random",true)),key.c_str(),tracks.data(),static_cast<uint32_t>(tracks.size()),static_cast<float>(j.numeric("gap_seconds",0))};playlist(ctx,d);});
}
} // namespace Plugins
